<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Sorting Visualizer</title>
<style>
  :root {
    --bg: #0f1117;
    --panel: #181b24;
    --bar: #4f8cff;
    --bar-active: #ffb454;
    --bar-done: #3ddc84;
    --text: #e6e9f0;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: var(--bg);
    color: var(--text);
    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    min-height: 100vh;
    padding: 24px;
  }
  h1 {
    font-size: 1.25rem;
    font-weight: 600;
    margin-bottom: 16px;
    letter-spacing: 0.02em;
  }
  #controls {
    display: flex;
    gap: 10px;
    margin-bottom: 20px;
  }
  button {
    background: var(--panel);
    color: var(--text);
    border: 1px solid #2a2f3d;
    border-radius: 8px;
    padding: 8px 18px;
    font-size: 0.95rem;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s;
  }
  button:hover { background: #232836; border-color: #3a4souvenir; border-color: #3a4256; }
  button:disabled { opacity: 0.5; cursor: not-allowed; }
  #bars {
    display: flex;
    align-items: flex-end;
    gap: 3px;
    height: 320px;
    width: min(90vw, 900px);
    background: var(--panel);
    border: 1px solid #2a2f3d;
    border-radius: 12px;
    padding: 16px;
  }
  .bar {
    flex: 1;
    background: var(--bar);
    border-radius: 3px 3px 0 0;
    min-width: 4px;
    transition: height 0.08s linear;
  }
  .bar.active { background: var(--bar-active); }
  .bar.done { background: var(--bar-done); }
  #status {
    margin-top: 12px;
    font-size: 0.85rem;
    color: #8b93a7;
    min-height: 1.2em;
  }
</style>
</head>
<body>
  <h1>Sorting Visualizer — Bubble Sort</h1>
  <div id="controls">
    <button id="sort">Sort</button>
    <button id="shuffle">Shuffle</button>
    <button id="reset">Reset</button>
  </div>
  <div id="bars"></div>
  <div id="status"></div>

<script>
(function () {
  var barsEl = document.getElementById('bars');
  var statusEl = document.getElementById('status');
  var sortBtn = document.getElementById('sort');
  var shuffleBtn = document.getElementById('shuffle');
  var resetBtn = document.getElementById('reset');

  var N = 40;
  var arr = [];
  var original = [];
  var animTimer = null;

  // Bubble-sort state (one comparison per sortStep call)
  var i = 0;        // outer pass index
  var j = 0;        // inner comparison index
  var swappedInPass = false;
  var done = false;

  function resetSortState() {
    i = 0;
    j = 0;
    swappedInPass = false;
    done = false;
  }

  function isAscending(a) {
    for (var k = 1; k < a.length; k++) {
      if (a[k - 1] > a[k]) return false;
    }
    return true;
  }

  function render(highlightA, highlightB) {
    var max = 0;
    for (var k = 0; k < arr.length; k++) {
      if (arr[k] > max) max = arr[k];
    }
    if (max <= 0) max = 1;

    barsEl.innerHTML = '';
    var allDone = isAscending(arr);
    for (var k2 = 0; k2 < arr.length; k2++) {
      var b = document.createElement('div');
      b.className = 'bar';
      b.style.height = Math.max(2, (arr[k2] / max) * 100) + '%';
      if (allDone && done) b.classList.add('done');
      else if (k2 === highlightA || k2 === highlightB) b.classList.add('active');
      b.title = String(arr[k2]);
      barsEl.appendChild(b);
    }
  }

  function newArray() {
    var a = [];
    for (var k = 0; k < N; k++) a.push(k + 1);
    // Fisher–Yates shuffle
    for (var m = a.length - 1; m > 0; m--) {
      var r = Math.floor(Math.random() * (m + 1));
      var t = a[m]; a[m] = a[r]; a[r] = t;
    }
    return a;
  }

  function stopAnimation() {
    if (animTimer !== null) {
      clearInterval(animTimer);
      animTimer = null;
    }
    sortBtn.disabled = false;
  }

  // --- Public API ---------------------------------------------------------

  function array() {
    return arr.slice();
  }

  function setArray(a) {
    stopAnimation();
    arr = a.slice().map(Number);
    original = arr.slice();
    resetSortState();
    render();
    statusEl.textContent = '';
  }

  function sorted() {
    return isAscending(arr);
  }

  // Performs exactly one bubble-sort comparison. Returns true once the
  // array is fully sorted, false otherwise.
  function sortStep() {
    if (done || isAscending(arr)) {
      done = true;
      render();
      return true;
    }

    var n = arr.length;
    var hiA = j, hiB = j + 1;

    if (arr[j] > arr[j + 1]) {
      var t = arr[j]; arr[j] = arr[j + 1]; arr[j + 1] = t;
      swappedInPass = true;
    }
    j++;

    if (j >= n - 1 - i) {
      // end of pass
      if (!swappedInPass) {
        done = true;
        render();
        return true;
      }
      j = 0;
      swappedInPass = false;
      i++;
      if (i >= n - 1) {
        done = true;
        render();
        return true;
      }
    }

    if (isAscending(arr) && j === 0) {
      // Early exit if a fresh pass would find nothing to do
      done = true;
      render();
      return true;
    }

    render(hiA, hiB);
    return false;
  }

  window.viz = {
    array: array,
    setArray: setArray,
    sortStep: sortStep,
    sorted: sorted
  };

  // --- UI wiring ----------------------------------------------------------

  sortBtn.addEventListener('click', function () {
    if (animTimer !== null) return;
    sortBtn.disabled = true;
    statusEl.textContent = 'Sorting…';
    animTimer = setInterval(function () {
      var finished = sortStep();
      if (finished) {
        stopAnimation();
        statusEl.textContent = 'Sorted!';
      }
    }, 12);
  });

  shuffleBtn.addEventListener('click', function () {
    setArray(newArray());
    statusEl.textContent = 'Shuffled.';
  });

  resetBtn.addEventListener('click', function () {
    stopAnimation();
    arr = original.slice();
    resetSortState();
    render();
    statusEl.textContent = 'Reset to last set array.';
  });

  // Initial state
  setArray(newArray());
})();
</script>
</body>
</html>
